"""Generates noise_vectors.json: a complete ESPHome Noise exchange with fixed
keys, produced by the Python `noise` library (noiseprotocol), the same
library aioesphomeapi uses. The Go tests replay it byte for byte.

Run from the repository root with a Python that has `noiseprotocol` and
`aioesphomeapi` installed (both come with ESPHome):

    python client/internal/espapi/testdata/gen_noise_vectors.py

Wire format follows aioesphomeapi/_frame_helper/noise.py.
"""

import base64
import json
from pathlib import Path

from aioesphomeapi.api_pb2 import HelloRequest, HelloResponse
from noise.connection import Keypair, NoiseConnection

PROTOCOL = b"Noise_NNpsk0_25519_ChaChaPoly_SHA256"
PROLOGUE = b"NoiseAPIInit\x00\x00"
PSK = bytes(range(1, 33))  # fixed test key
CLIENT_EPHEMERAL = bytes(range(0x40, 0x60))
SERVER_EPHEMERAL = bytes(range(0x80, 0xA0))
DEVICE_NAME = "knockblock"
DEVICE_MAC = "AA:BB:CC:DD:EE:FF"


def frame(data: bytes) -> bytes:
    return bytes((0x01, len(data) >> 8, len(data) & 0xFF)) + data


def inner(msg_type: int, payload: bytes) -> bytes:
    return bytes(
        (msg_type >> 8, msg_type & 0xFF, len(payload) >> 8, len(payload) & 0xFF)
    ) + payload


def party(initiator: bool, ephemeral: bytes) -> NoiseConnection:
    conn = NoiseConnection.from_name(PROTOCOL)
    if initiator:
        conn.set_as_initiator()
    else:
        conn.set_as_responder()
    conn.set_psks(PSK)
    conn.set_prologue(PROLOGUE)
    conn.set_keypair_from_private_bytes(Keypair.EPHEMERAL, ephemeral)
    conn.start_handshake()
    return conn


def main() -> None:
    client = party(True, CLIENT_EPHEMERAL)
    server = party(False, SERVER_EPHEMERAL)

    msg1 = client.write_message()
    server.read_message(msg1)
    msg2 = server.write_message()
    client.read_message(msg2)
    assert client.handshake_finished and server.handshake_finished

    # Client: empty ClientHello frame, then the handshake frame
    # (_send_hello_handshake).
    client_handshake = b"\x01\x00\x00" + frame(b"\x00" + msg1)
    # Server: ServerHello (chosen protocol, name\0, mac\0), then the
    # handshake response with a 0x00 "no error" byte.
    server_hello = frame(
        b"\x01" + DEVICE_NAME.encode() + b"\x00" + DEVICE_MAC.encode() + b"\x00"
    )
    server_handshake = frame(b"\x00" + msg2)

    hello = HelloRequest(
        client_info="KnockBlock", api_version_major=1, api_version_minor=19
    ).SerializeToString()
    hello_resp = HelloResponse(
        api_version_major=1, api_version_minor=19, server_info="2026.10.0", name=DEVICE_NAME
    ).SerializeToString()
    client_frame = frame(client.encrypt(inner(1, hello)))
    server_frame = frame(server.encrypt(inner(2, hello_resp)))

    vectors = {
        "comment": "Generated by gen_noise_vectors.py with the Python noise library; do not edit.",
        "psk": base64.b64encode(PSK).decode(),
        "client_ephemeral": CLIENT_EPHEMERAL.hex(),
        "server_ephemeral": SERVER_EPHEMERAL.hex(),
        "device_name": DEVICE_NAME,
        "device_mac": DEVICE_MAC,
        "client_handshake": client_handshake.hex(),
        "server_hello": server_hello.hex(),
        "server_handshake": server_handshake.hex(),
        "hello_request": hello.hex(),
        "client_frame": client_frame.hex(),
        "hello_response": hello_resp.hex(),
        "server_frame": server_frame.hex(),
    }
    out = Path(__file__).with_name("noise_vectors.json")
    out.write_text(json.dumps(vectors, indent=2) + "\n")
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
